def find_arithmetic_progressions(n, sequence):
    for i in range(1, n):
        for j in range(i + 1, n):
            diff1 = sequence[j] - sequence[i]
            progression1 = [sequence[i]]
            progression2 = [sequence[j]]
            for k in range(n):
                if k != i and k != j:
                    if sequence[k] - sequence[i] == diff1:
                        progression1.append(sequence[k])
                    else:
